import re
import os
import logging
import pkg_resources
from ta_kiss_core.sshconnection.sshconnection import SshConnection
from ta_kiss_core.method_show_type import log_method_name


class enb_ttitrace(object):

    def __init__(self, enb_ip, host_ip):
        self._log = logging.getLogger(__name__)
        self._log.setLevel(logging.DEBUG)
        self._enb_ip = enb_ip
        self._host_ip = host_ip
        self._node_type = None
        self._hw_type = None
        self._cellmapping = self._get_cell_mapping_info()

    def get_nb_core_id(self, node_type, cell_id):
        """get core id when nb is True"""
        dl_core_ids = self.get_core_id(node_type, cell_id)
        return [",".join("{},{}".format(core, core) for core in dl_core_ids[0].split(',')), dl_core_ids[1]]

    def get_core_id(self, node_type, cell_id):
        """

        :param node_type:
        :param cell_id:
        :param alias:
        :return:
        """
        cell_info_table = self._cellmapping
        hw_type = self.get_hw_type(cell_info_table)
        return_core = ''
        for cell in str(cell_id).split(','):
            if node_type.upper() == 'UL':
                core = self._get_tti_ul_node(cell)
            if node_type.upper() == 'DL':
                core = self._get_tti_dl_node(cell)
            if node_type.upper() == 'ALL':
                ul_core = self._get_tti_ul_node(cell)
                dl_core = self._get_tti_dl_node(cell)
                core = '{},{}'.format(dl_core, ul_core)
            return_core = return_core + ',' + core
        return [return_core.strip(','), hw_type]

    @log_method_name
    def get_all_cell_core_id(self, node_type):
        """

        :param enb_ip:
        :param host_ip:
        :param node_type:
        :param alias:
        :return:
        """
        cell_info_table = self._cellmapping
        hw_type = self.get_hw_type(cell_info_table)
        cell_ids = self.get_all_cell_ids(cell_info_table)
        if node_type == 'DL':
            return [self.get_all_core_id_for_one_node_type('DL', cell_ids), hw_type]
        if node_type == 'UL':
            return [self.get_all_core_id_for_one_node_type('UL', cell_ids), hw_type]
        if node_type == 'ALL':
            dl = self.get_all_core_id_for_one_node_type('DL', cell_ids)
            ul = self.get_all_core_id_for_one_node_type('UL', cell_ids)
            dl_list = dl.split(',')
            ul_list = ul.split(',')
            cores = ''
            for i in range(0, len(dl_list)):
                cores = cores + dl_list[i] + ',' + ul_list[i] + ','
            return [cores.strip(','), hw_type]

    def get_all_cell_ids(self, cell_info_table):
        """

        :param cell_info_table:
        :return:
        """
        cell_id = []
        for info in cell_info_table.splitlines():
            if info.split()[0].isdigit():
                cell_id.append(info.split()[0])
        self._log.debug('all cell id is {}'.format(cell_id))
        return cell_id

    def get_intact_core_id(self, node_type, cell_id):
        """

        :param enb_ip:
        :param host_ip:
        :param node_type:
        :param cell_id:
        :return:
        """
        if node_type not in ['UL', 'DL']:
            raise Exception('{} is not support, must be UL or DL'.format(node_type))
        cell_info_table = self._cellmapping
        coreIds = []
        if cell_id == 'ALL':
            cells = self.get_all_cell_ids(cell_info_table)
        else:
            cells = str(cell_id).split(',')
        for cell in cells:
            if not cell.isdigit():
                raise Exception("cell id '{}' is not a correct format, it should like '11'".format(cell))
            coreIds.append(self._get_one_cell_intact_core_id(cell_info_table, node_type, cell))
        return coreIds[0] if len(coreIds) == 1 else coreIds

    @log_method_name
    def get_all_core_id_for_one_node_type(self, node_type, cell_ids):
        """

        :param cell_info_table:
        :return:
        """
        cores = ''
        for cell_id in cell_ids:
            if node_type == 'DL':
                core = self._get_tti_dl_node(cell_id)
            if node_type == 'UL':
                core = self._get_tti_ul_node(cell_id)
            cores = '{}{},'.format(cores, core)
        return cores.strip(',')

    def _get_tti_dl_node(self, lcr):
        return self._get_node(lcr, "MACDLTTI")

    def _get_tti_ul_node(self, lcr):
        return self._get_node(lcr, "MACULTTI")

    def _get_node(self, lcr, table):
        lcr = lcr or self._cellmapping.splitlines()[1].split()[0]
        column = self._get_table_column(self._cellmapping, table)
        return self._extract_node(self._cellmapping, lcr, column)

    def _get_one_cell_intact_core_id(self, cell_info_table, node_type, cell_id):
        ul_tti = self._get_table_column(cell_info_table, 'MACULTTI')
        dl_tti = self._get_table_column(cell_info_table, 'MACDLTTI')
        for info in cell_info_table.splitlines():
            if info.split()[0].isdigit() and str(info.split()[0]) == str(cell_id):
                return info.split()[ul_tti] if node_type == 'UL' else info.split()[dl_tti]
        raise Exception("Do not get {} core id".format(cell_id))

    def _get_cell_mapping_info(self):
        tool_path = '{}/{}'.format(pkg_resources.resource_filename('ta_ttitrace', "resources"), 'getcellmapping')
        self.execute_command_by_ssh('sudo chmod u+x {}'.format(tool_path), self._host_ip)
        cmd = 'sudo {} {} 15007'.format(tool_path, self._enb_ip)
        out = self.execute_command_by_ssh(cmd, self._host_ip)[0]
        output = self._extract_table_from_output("{}".format(out))
        self._log.debug("Tool query result:{}".format(output))
        return output

    def _extract_table_from_output(self, out):
        """

        :param out:
        :return:
        """
        try:
            return re.search('(lcr lnCel.*\n[\w\s.-]+)', out, re.MULTILINE).group(1)
        except Exception:
            raise Exception('Table not found.')

    def _extract_node(self, cell_info_table, lcr, node):
        cells = cell_info_table.splitlines()
        for cell in cells:
            if cell.split()[0] == lcr:
                return cell.split()[node][:10] if len(cell.split()[node]) >= 10 else cell.split()[node][:6]
        raise Exception('{} did not match any local cell resource'.format(lcr))

    def _get_table_column(self, cell_info_table, table):
        cells = cell_info_table.splitlines()
        tables = cells[0].split()
        for index in range(0, len(tables)):
            if table == tables[index]:
                return index
        raise Exception("{} did not match any table name".format(table))

    def get_platform_type(self):
        """Get platform type from cell mapping info

        :param enb_ip:
        :param host_ip:
        :return:
        """
        cell_info_table = self._cellmapping
        l2pooltype_index = self._get_table_column(cell_info_table, 'L2PoolType')
        l2pooltype = cell_info_table.splitlines()[-1].split()[l2pooltype_index]
        platform = 'FSM_ARM' if "FSMr4" in l2pooltype else 'FSM'
        if "massivemimo" in l2pooltype.lower():
            platform = 'MassiveMimo'
        if "LF_" in l2pooltype:
            platform = 'LionFsih'
        if "SNF_" in l2pooltype:
            platform = 'SnowFish'
        return platform

    @log_method_name
    def get_hw_type(self, cell_info_table):
        """

        :param cell_info_table:
        :return:
        """
        lines = cell_info_table.splitlines()
        line_info = lines[-1]
        return 'FSMr3' if 'FSMr3' in line_info else 'FSMr4'

    def execute_command_by_ssh(self, command, host_ip):
        """
        """
        ssh_client = SshConnection(host_ip, 'ute', 'ute')
        try:
            ssh_client._setup()
            self._log.info("execute command:{}".format(command))
            ret = ssh_client.execute(command)
            self._log.debug(ret)
        except Exception as e:
            raise Exception("{} execute fail!Detail is {}".format(command, str(e)))
        finally:
            ssh_client._teardown()
            return ret

    def node_type_and_hw_type_in_start_ttitrace(self, node_type, hw_type):
        """
        save node type and hw type
        :param node_type:
        :param hw_type:
        :return:
        """
        self._node_type = node_type
        self._hw_type = hw_type

    def update_download_file_name(self, ttitrace_files):
        """
        """
        if self._hw_type != 'FSMr3':
            return ttitrace_files
        if self._node_type != 'UL':
            return ttitrace_files
        new_ttitrace_files = []
        for tti_file in ttitrace_files:
            if '_dl_' in os.path.split(tti_file)[1]:
                new_name = os.path.join(os.path.split(tti_file)[0],
                                        os.path.split(tti_file)[1].replace('_dl_', '_ul_'))
                self.execute_command_by_ssh('mv {} {}'.format(tti_file, new_name), self._host_ip)
                new_ttitrace_files.append(new_name)
            else:
                new_ttitrace_files.append(tti_file)
        return new_ttitrace_files
